/* ── angle helpers (degrees, screen coords: +y down) ───────────────────── */
function rad(d) { return d * Math.PI / 180; }
function cosd(d) { return Math.cos(rad(d)); }
function sind(d) { return Math.sin(rad(d)); }
function atan2d(dy, dx) { return Math.atan2(dy, dx) * 180 / Math.PI; }
function arcD(cx, cy, r, a0, a1) {
  return 'M' + (cx + r * cosd(a0)) + ' ' + (cy + r * sind(a0)) +
    ' A' + r + ' ' + r + ' 0 0 1 ' + (cx + r * cosd(a1)) + ' ' + (cy + r * sind(a1));
}
function rayInt(o1, a1, o2, a2) {
  var d1x = cosd(a1), d1y = sind(a1), d2x = cosd(a2), d2y = sind(a2);
  var den = d1x * d2y - d1y * d2x;
  if (Math.abs(den) < 1e-9) return null;
  var s = ((o2.x - o1.x) * d2y - (o2.y - o1.y) * d2x) / den;
  return { x: o1.x + s * d1x, y: o1.y + s * d1y, s: s };
}
function interactive(el, tip, title, body) {
