  .fill('#ffffff').stroke({ color: '#1c1c1c', width: 3, linejoin: 'round' });
interactive(boat, 'Boat — its distance d is unknown', 'The unknown distance d',
  'The boat is never ranged directly. Single observer: d = h / tan α from the known height and the dip angle. Two observers: d comes from intersecting two sight lines a known baseline t apart. Both are pure geometry — the same principle behind stereo depth.');

var gDyn = draw.group();

function mkText(str, x, y, o) {
  o = o || {};
  var t = gDyn.text(String(str));
  t.font({ family: o.serif ? 'Georgia, serif' : 'sans-serif', size: o.size || 14, anchor: o.anchor || 'start' });
  if (o.italic) t.attr('font-style', 'italic');
  if (o.bold) t.attr('font-weight', 'bold');
  t.fill(o.fill || '#111111');
