  interactive(arc, 'Dip angle α (measured)', 'Dip angle α',
    'α is the angle below the horizontal horizon line at which the boat appears. With a ±0.4° measurement error the estimate d = h / tan α is only approximate — notice the readout error grow when h (and so α) is small.');

  var obs = gDyn.circle(24).center(MAST_X, oy).fill('#ffffff').stroke({ color: '#1c1c1c', width: 3.5 });
  interactive(obs, 'Observer at height h', 'One observer, known height',
    'The observer sights the horizon and the boat. The known height h plus the dip angle α fix a right triangle, so the distance d = h / tan α follows from trigonometry alone.');

  mkText('α', MAST_X + 82 * cosd(alpha / 2), oy + 82 * sind(alpha / 2) + 2, { serif: 1, italic: 1, size: 24 });
  mkText('h', MAST_X - 16, (oy + WATER_Y) / 2 + 7, { serif: 1, italic: 1, size: 24, anchor: 'end' });
  mkText('d?', 418, WATER_Y + 32, { serif: 1, italic: 1, size: 28 });

  readout([
    { s: 'Single observer · height h = ' + state.h + ' m', b: 1 },
    { s: 'dip angle α = ' + alpha.toFixed(1) + '°  (measured ' + alphaM.toFixed(1) + '°)' },
    { s: 'd = h / tan α  ≈  ' + Math.round(dEst) + ' m    (true d = ' + Math.round(D_TRUE) + ' m)' },
    { s: 'error ≈ ' + Math.abs(Math.round(dEst - D_TRUE)) + ' m  from the ±' + SIGMA + '° angle error' }
  ]);
}

/* ── two-observer triangulation ────────────────────────────────────────── */
function renderTri() {
  var o1 = { x: MAST_X, y: 64 };
  var o2 = { x: MAST_X, y: 64 + SCALE * state.t };
  var a1 = atan2d(BOAT_Y - o1.y, BOAT_X - o1.x);
  var a2 = atan2d(BOAT_Y - o2.y, BOAT_X - o2.x);
  var alpha = 90 - a1, beta = 90 - a2, par = beta - alpha;
  var alphaM = alpha + SIGMA, betaM = beta - SIGMA;
  var r1 = a1 - SIGMA, r2 = a2 + SIGMA;          // measured ray directions
  var hit = rayInt(o1, r1, o2, r2);

  var mast = gDyn.rect(5, WATER_Y - 56).move(MAST_X - 2.5, 56).fill('#1c1c1c');
  interactive(mast, 'Observation mast', 'Two observers, one mast',
    'Both observers stand on the same structure, separated by a surveyed baseline t. Each sights the boat; the two sight lines and the baseline form a triangle that determines d.');
  var base = seg(o1.x, o1.y, o2.x, o2.y, '#ffd27a', 8);
  interactive(base, 'Known baseline t', 'The baseline t',
    'The separation t is the only length that must be known. The parallax angle β − α grows with t; as t shrinks the sight lines become nearly parallel and the fix on d collapses — exactly why stereo depth fails for distant objects.');

  seg(o1.x, o1.y, BOAT_X - 6, BOAT_Y, '#1c1c1c', 2.5);   // true sight lines
  seg(o2.x, o2.y, BOAT_X - 6, BOAT_Y, '#1c1c1c', 2.5);

  // measured (erroneous) rays
  var len1 = hit ? Math.max(0, Math.min(hit.s, 780)) : 780;
  var e1 = { x: o1.x + len1 * cosd(r1), y: o1.y + len1 * sind(r1) };
  seg(o1.x, o1.y, e1.x, e1.y, '#c0392b', 2, '6,5');
  var len2 = hit ? Math.max(0, Math.min(Math.hypot(hit.x - o2.x, hit.y - o2.y), 780)) : 780;
  var e2 = { x: o2.x + len2 * cosd(r2), y: o2.y + len2 * sind(r2) };
  seg(o2.x, o2.y, e2.x, e2.y, '#c0392b', 2, '6,5');

  var onScreen = hit && hit.s > 0 && hit.s <= 780 && hit.x <= 890 && hit.y <= 632;
  if (onScreen) {
    var x1 = seg(hit.x - 9, hit.y - 9, hit.x + 9, hit.y + 9, '#c0392b', 3);
    var x2 = seg(hit.x - 9, hit.y + 9, hit.x + 9, hit.y - 9, '#c0392b', 3);
    interactive(x1, 'Estimated boat position', 'Estimated position',
      'The dashed rays are drawn with a ±0.4° measurement error; where they cross is the estimated boat position. Its offset from the real boat is the distance error — shrink t and watch the crossing fly away.');
    interactive(x2, 'Estimated boat position', 'Estimated position',
      'The dashed rays are drawn with a ±0.4° measurement error; where they cross is the estimated boat position. Its offset from the real boat is the distance error — shrink t and watch the crossing fly away.');
  } else {
    var d1 = gDyn.circle(8).center(e1.x, e1.y).fill('#c0392b');
    var d2 = gDyn.circle(8).center(e2.x, e2.y).fill('#c0392b');
    interactive(d1, 'Rays still have not met', 'Fix lost',
      'With such a small baseline the measured rays are nearly parallel: their intersection lies far beyond the view. Tiny angle errors now produce enormous distance errors — the estimate is worthless.');
    interactive(d2, 'Rays still have not met', 'Fix lost',
      'With such a small baseline the measured rays are nearly parallel: their intersection lies far beyond the view. Tiny angle errors now produce enormous distance errors — the estimate is worthless.');
  }

  gDyn.path(arcD(o1.x, o1.y, 50, a1, 90)).fill('none').stroke({ color: '#1c1c1c', width: 2 });
  gDyn.path(arcD(o2.x, o2.y, 44, a2, 90)).fill('none').stroke({ color: '#1c1c1c', width: 2 });

  var c1 = gDyn.circle(24).center(o1.x, o1.y).fill('#ffffff').stroke({ color: '#1c1c1c', width: 3.5 });
  var c2 = gDyn.circle(24).center(o2.x, o2.y).fill('#ffffff').stroke({ color: '#1c1c1c', width: 3.5 });
  interactive(c1, 'Upper observer — angle α', 'Two observers triangulate',
    'Each observer sights the same boat. Baseline t plus angles α and β fully determine the triangle, so d follows without any horizon reference — the same principle as stereo vision with two eyes.');
  interactive(c2, 'Lower observer — angle β', 'Two observers triangulate',
    'Each observer sights the same boat. Baseline t plus angles α and β fully determine the triangle, so d follows without any horizon reference — the same principle as stereo vision with two eyes.');

  mkText('α', o1.x + 70 * cosd((a1 + 90) / 2), o1.y + 70 * sind((a1 + 90) / 2) + 2, { serif: 1, italic: 1, size: 24 });
  mkText('β', o2.x + 62 * cosd((a2 + 90) / 2), o2.y + 62 * sind((a2 + 90) / 2) + 2, { serif: 1, italic: 1, size: 24 });
  mkText('t', MAST_X - 16, (o1.y + o2.y) / 2 + 7, { serif: 1, italic: 1, size: 24, anchor: 'end' });
  mkText('d?', 418, WATER_Y + 32, { serif: 1, italic: 1, size: 28 });

  var dEst = (hit && hit.s > 0) ? (hit.x - MAST_X) / SCALE : NaN;
  readout([
    { s: 'Two observers · baseline t = ' + state.t + ' m', b: 1 },
    { s: 'α = ' + alpha.toFixed(1) + '°   β = ' + beta.toFixed(1) + '°   →   parallax β−α = ' + par.toFixed(1) + '°' },
    { s: onScreen ? ('d ≈ ' + Math.round(dEst) + ' m    (true d = ' + Math.round(D_TRUE) + ' m, error ' + Math.abs(Math.round(dEst - D_TRUE)) + ' m)') : 'd unreliable — measured rays do not converge in view' },
    { s: 'smaller t ⇒ parallax → 0 ⇒ error explodes (stereo limit)' }
  ]);
}

function render() {
  gDyn.clear();
  if (state.method === 'single') renderSingle(); else renderTri();
}

/* ── controls ──────────────────────────────────────────────────────────── */
function setMethod(m) {
  state.method = m;
  document.getElementById('mSingle').classList.toggle('active', m === 'single');
  document.getElementById('mTri').classList.toggle('active', m === 'tri');
  document.getElementById('observerHeightInput').disabled = (m !== 'single');
  document.getElementById('baselineSeparationInput').disabled = (m !== 'tri');
  document.getElementById('hLab').style.opacity = (m === 'single') ? 1 : 0.45;
  document.getElementById('tLab').style.opacity = (m === 'tri') ? 1 : 0.45;
  render();
}
function update_observerHeight(v) { state.h = v; if (state.method === 'single') render(); }
function update_baselineSeparation(v) { state.t = v; if (state.method === 'tri') render(); }

/* ── demo steps ────────────────────────────────────────────────────────── */
var steps = [
  { title: 'One observer, known height', narration: 'Standing at height h above the water, the observer measures the dip angle α between the horizon and the boat. Together with h this fixes a right triangle, so d follows from trigonometry alone.', state: { methodView: 'Single observer (height + horizon)', observerHeight: 60 } },
  { title: 'Height changes the estimate', narration: 'Drag the height slider: for the same measured angle α, a taller vantage point implies a larger distance d. The horizon reference only yields distance because h is known.', state: { methodView: 'Single observer (height + horizon)', observerHeight: 110 } },
  { title: 'Two observers triangulate', narration: 'Switch methods: now two observers separated by a known baseline t each sight the boat, measuring angles α and β. The boat sits at the intersection of the two sight lines — no horizon reference needed.', state: { methodView: 'Two observers (triangulation)', baselineSeparation: 40 } },
  { title: 'Baseline controls reliability', narration: 'Shrink the separation t toward zero: the two sight lines become nearly parallel and the intersection point — hence d — becomes extremely sensitive to tiny angle errors. A wide baseline gives a well-conditioned fix, just like the separation between two eyes or cameras in stereo vision.', state: { methodView: 'Two observers (triangulation)', baselineSeparation: 10 } }
];
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep].state;
  if (s.methodView) setMethod(s.methodView.indexOf('Single') === 0 ? 'single' : 'tri');
  if (s.observerHeight != null) {
    document.getElementById('observerHeightInput').value = s.observerHeight;
    document.getElementById('observerHeightVal').value = s.observerHeight;
    state.h = s.observerHeight;
  }
  if (s.baselineSeparation != null) {
    document.getElementById('baselineSeparationInput').value = s.baselineSeparation;
    document.getElementById('baselineSeparationVal').value = s.baselineSeparation;
    state.t = s.baselineSeparation;
  }
  render();
  document.getElementById('demoNarration').textContent = steps[curStep].title + ' — ' + steps[curStep].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' of ' + steps.length;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ── init ──────────────────────────────────────────────────────────────── */
setMethod('single');
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

